class DiagnosisProbe:
    def __init__(self, view, device):
        self.view, self.device = view, device

    def run_full_diagnosis(self, train_loader):
        # Require an independent diagnostic loader or documented cached tensors.
        cached = obtain_independent_probe_cache(train_loader)
        state = snapshot_rngs_module_flags_and_supported_mutable_state(self.view.model)
        try:
            self.view.model.eval()
            with torch.no_grad():
                metrics = existing_embedding_and_margin_probes(cached)
                for sequence, positives, negatives in cached:
                    for prefix, target, negative in independent_valid_prefixes(sequence, positives, negatives):
                        if len(prefix) < 3:
                            continue
                        variants = prespecified_anchor_fixed_variants(prefix, seeds=FIXED_FIVE_SEEDS)
                        baseline = score_last_valid_state(prefix, target, negative)
                        record_training_dependence(baseline, variants, target, negative)
                attach_counts_availability_and_definitions(metrics)
                return {'metrics': metrics, 'metric_definitions': definitions(metrics)}
        finally:
            restore_supported_mutable_state_and_each_module_flag(state)
            restore_all_registered_rng_states(state)

# Optional validation hook; never accepts test data.
def audit_validation(view, permitted_records, fixed_ordered_candidates):
    state = snapshot_probe_transaction(view.model)
    try:
        view.model.eval()
        with torch.no_grad():
            for category in FOUR_CATEGORIES:
                for user in permitted_records[category]:
                    history = user.history
                    candidates = fixed_ordered_candidates[category][user.id]
                    baseline = score_fixed_candidates(view, history, candidates)
                    for variant in prespecified_variants(history):
                        changed = score_fixed_candidates(view, variant, candidates)
                        record_paired_hits_ranks_overlap(baseline, changed)
            return paired_category_bootstrap(replicates=10000, seed=42)
    finally:
        restore_probe_transaction(state)

# Before search: register configurations, checkpoint schedule, budget and stopping rule.
# Fit simple baselines from training interactions only.
# Test the prespecified recency-residual ablation; synchronize predictor writer if changed.
# Select solely through the host's unchanged macro validation HR@10.
# Freeze the selected configuration before independent held-out evaluation.

